  "result": "[{\"saved_id\": \"saved_seed_001\", \"user_id\": \"usr_wang_fang\", \"case_id\": \"case_001\", \"note\": \"最贴近我的情况：对方转账时也先扣了利息(砍头息)，借条金额和实际到账不一样。这案子按实际到账认定本金，约定的高息也被砍到LPR四倍，可作主张参照。\", \"saved_at\": \"2026-05-12T09:15:00Z\", \"case\": {\"case_id\": \"case_001\", \"case_number\": \"(2025)浙0106民初13201号\", \"title\": \"张某诉李某民间借贷纠纷案（砍头息·本金按实际认定）\", \"court_id\": \"court_hz_xihu\", \"court_name\": \"杭州市西湖区人民法院\", \"case_type\": \"合同纠纷\", \"cause\": \"民间借贷纠纷\", \"judgment_date\": \"2025-10-21\", \"outcome\": \"部分支持\", \"summary\": \"出借人转账时预先扣除两个月利息，借条载明50万但实际到账48万，法院按实际出借金额认定本金。\"}}, {\"saved_id\": \"saved_seed_002\", \"user_id\": \"usr_wang_fang\", \"case_id\": \"case_009\", \"note\": \"备用参照：被告住所地在外地，但出借人在自己住所地起诉，法院认定接收货币一方(出借人)所在地有管辖权——我可以在杭州起诉，不用跑去宁波。\", \"saved_at\": \"2026-05-14T20:40:00Z\", \"case\": {\"case_id\": \"case_009\", \"case_number\": \"(2025)浙0106民初09015号\", \"title\": \"邹某诉钱某管辖权异议案（接收货币一方所在地）\", \"court_id\": \"court_hz_xihu\", \"court_name\": \"杭州市西湖区人民法院\", \"case_type\": \"合同纠纷\", \"cause\": \"民间借贷纠纷\", \"judgment_date\": \"2025-05-26\", \"outcome\": \"驳回\", \"summary\": \"被告以应由被告住所地管辖提出管辖异议，法院认定出借人住所地为合同履行地，驳回异议。\"}}]"
}

