  "result": "{\"article_id\": \"art_mcc_188\", \"statute_id\": \"stat_mcc\", \"statute_name\": \"中华人民共和国民法典\", \"article_no\": \"第一百八十八条\", \"heading\": \"诉讼时效\", \"text\": \"向人民法院请求保护民事权利的诉讼时效期间为三年。诉讼时效期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算。\"}"
}

structuredContent:
