  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"12304875-c9eb-43df-8989-912042401473\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"📌\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"建档日期：2026-05-20　|　阶段：诉前准备　|　拟管辖：杭州市西湖区人民法院　|　主张本金：56万元（借条合计60万元，第一笔预扣利息4万元）\"}}]}}, {\"object\": \"block\", \"id\": \"f8163f77-4e72-4ced-8fa7-3e7298cff242\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_1\", \"heading_1\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"一、案件概况\"}}]}}, {\"object\": \"block\", \"id\": \"899b513d-5357-46f3-8788-0074f8cea668\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"王芳与陈强系老同学。2023年6月、9月，陈强以项目周转为由分两笔向王芳借款，均出具借条、约定月利率2%、借期一年。到期后陈强长期拖欠，2025年2月15日仅微信偿还2万元并承诺继续还款，此后再次失联式拖延。王芳决定起诉追偿本息。\"}}]}}, {\"object\": \"block\", \"id\": \"1bbce61e-f85f-4b76-882b-6c8487197c9a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"paragraph\", \"paragraph\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"近期线索：陈强名下宁波市海曙区房产正在中介挂牌“急售、可低于市场价”，存在转移财产风险，需优先评估财产保全。\"}}]}}, {\"object\": \"block\", \"id\": \"aae187a4-3d5b-4d07-8a04-7782ba0b9145\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_1\", \"heading_1\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"二、当事人\"}}]}}, {\"object\": \"block\", \"id\": \"17dee9cb-4156-44ac-85***\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"原告（出借人）：王芳，住杭州市西湖区，经营服装店。\"}}]}}, {\"object\": \"block\", \"id\": \"39ff8d78-3ea9-4c57-844e-df27959dce9d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"被告（借款人）：陈强，住宁波市海曙区，与王芳系老同学。\"}}]}}, {\"object\": \"block\", \"id\": \"9ee13c08-cc49-4ba4-8e9a-5a9453bcf96a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"担保人：周国华（老周），仅在第一笔借条上签字“担保”，未约定保证方式与保证期间。\"}}]}}, {\"object\": \"block\", \"id\": \"0d3238a3-c9ac-4c8d-833d-a1dd599cb9d8\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"陈强配偶：刘敏。林涛反映陈强借款用于炒股加杠杆，刘敏当时明确不认此账。\"}}]}}, {\"object\": \"block\", \"id\": \"50a0b6e6-2adb-4564-8153-c3232b8281f3\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_1\", \"heading_1\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"三、两笔借款\"}}]}}, {\"object\": \"block\", \"id\": \"c0744124-6550-4811-8079-ad157daf6c5a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"第一笔：2023-06-10\"}}]}}, {\"object\": \"block\", \"id\": \"cb40c118-acf5-41f4-8445-b67b1b8e4f40\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"借条载明：人民币40万元，月利率2%，借期一年，2024-06-10前还清；借款人陈强，担保人周国华签字。\"}}]}}, {\"object\": \"block\", \"id\": \"4a57da2e-cefe-4557-894e-85fdd73b7a8b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"实际交付：工商银行转账36万元。陈强当场称“头两个月利息先扣”，4万元为预扣利息，未实际到账。\"}}]}}, {\"object\": \"block\", \"id\": \"63b7acf6-396c-439a-8ec8-3557084308e7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"证据：借条原件（已拍照备份）、工行转账回单（备注“借款”）。\"}}]}}, {\"object\": \"block\", \"id\": \"e9ff4e56-07ef-4a6a-817e-169d70fdc5d3\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"第二笔：2023-09-15\"}}]}}, {\"object\": \"block\", \"id\": \"1c7d3723-6491-4eed-8375-db4d7a950504\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"借条载明：人民币20万元现金，月利率2%，借期一年（2024-09-15到期）。\"}}]}}, {\"object\": \"block\", \"id\": \"ee37e08a-afc7-4588-8d16-6616bfc2e42b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"实际交付：王芳称以家中现金分次凑齐、当面交付；无银行转账、无收条、无取现单据。\"}}]}}, {\"object\": \"block\", \"id\": \"03b8d79f-2c82-4b4b-8c74-df8986903b20\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"证据：借条原件（已拍照备份）；出借能力佐证为服装店2023年上半年账目（净利约8万元+积蓄）。\"}}]}}, {\"object\": \"block\", \"id\": \"c3acc334-602c-4462-81f0-eaa1b0e11bcd\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"还款与催收\"}}]}}, {\"object\": \"block\", \"id\": \"ba357976-b83b-46e7-817a-bccdd5308ef5\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"2025-02-15：陈强微信转账2万元，并称“先还你2万应应急，剩下的我肯定会还，再宽限我点时间”。此后多次催讨无果。\"}}]}}, {\"object\": \"block\", \"id\": \"114df313-41c8-4941-897e-9c