id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"✅ 第二笔借条原件 + 照片备份（20万元现金，月息2%）\"}}]}}, {\"object\": \"block\", \"id\": \"314ac3e3-5403-48c1-8ba1-2ace8a724e06\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"✅ 微信催收记录 + 2025-02-15 还款2万元记录（手机原件）\"}}]}}, {\"object\": \"block\", \"id\": \"652668e6-e6ca-47cc-8257-82b33d372170\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"✅ 服装店2023年上半年账目（出借能力佐证）\"}}]}}, {\"object\": \"block\", \"id\": \"cbde6204-d969-4f00-8a15-655c3c4ca085\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"✅ 2025-09 向陈强发送的催款邮件\"}}]}}, {\"object\": \"block\", \"id\": \"914c6d9c-02d5-4221-8e23-161ffc20c698\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"⚠️ 缺口：第二笔20万元无取现/交付凭证；需补银行流水、微信中对60万元或20万元的确认、证人证言等\"}}]}}, {\"object\": \"block\", \"id\": \"5416a7e8-f7cb-4aaa-88f4-b87aa4c68ca9\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"⚠️ 缺口：陈强房产挂牌信息（截图/中介挂牌页），用于保全必要性说明\"}}]}}, {\"object\": \"block\", \"id\": \"ebc2dd7a-d4a0-4655-8062-3c19781eb5f0\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_1\", \"heading_1\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、已收藏的同类判例（2件）\"}}]}}, {\"object\": \"block\", \"id\": \"6ce8cdb8-66e9-4740-89a2-172eeb248a03\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"case_001｜(2025)浙0106民初13201号｜杭州市西湖区人民法院｜砍头息·本金按实际认定：借条50万、实际到账48万，法院按实际出借金额认定本金。收藏备注：“最贴近我的情况”。\"}}]}}, {\"object\": \"block\", \"id\": \"1918ad70-80b1-40c4-8a46-d8a557c75d7b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"case_009｜(2025)浙0106民初09015号｜杭州市西湖区人民法院｜管辖权异议：被告主张应由住所地管辖，法院认定出借人住所地为合同履行地，驳回异议。收藏备注：“可以在杭州起诉，不用跑去宁波”。\"}}]}}, {\"object\": \"block\", \"id\": \"ee103560-b7e0-4192-8e40-c151b956f44b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_1\", \"heading_1\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"六、初步法律判断（待律师确认）\"}}]}}, {\"object\": \"block\", \"id\": \"574401af-74b8-4d01-8a15-115d9ecf7731\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"本金：第一笔按实际到账36万元认定，不是借条40万元（《民法典》第670条、《民间借贷司法解释》第26条）。第二笔20万元借条+现金交付，需另行证明实际交付。合计主张本金暂定56万元。\"}}]}}, {\"object\": \"block\", \"id\": \"0ea5f9ae-d7cc-4b77-872b-a6c00087155c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"利息：约定月息2%（年24%）超过合同成立时一年期LPR四倍，超出部分不受保护（《民间借贷司法解释》第25条）。起诉时按四倍上限主张，具体数额待按2023年6月/9月LPR核算。\"}}]}}, {\"object\": \"block\", \"id\": \"6419daf5-9dfc-47e7-8ae9-845dec33a27f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉讼时效：三年（《民法典》第188条）。2025-02-15部分还款并承诺继续履行，构成时效中断并重新计算（第195条），目前未过时效。\"}}]}}, {\"object\": \"block\", \"id\": \"fd63287f-4f08-4a3c-8e22-74a6ba7c67f2\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"管辖：可在杭州市西湖区人民法院起诉。民间借贷以接收货币一方（出借人王芳）所在地为合同履行地（《民诉法解释》第18条；判例case_009）。\"}}]}}, {\"object\": \"block\", \"id\": \"a325d411-2754-41c3-8926-474b506bec84\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"前置程序：民间借贷为普通合同纠纷，可直接起诉，无须先仲裁或调解（杭州法院立案须知①）。\"}}]}}, {\"object\": \"block\", \"id\": \"03ab66aa-ec14-4d41-80ae-fbd93b9a6d12\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"担保人周国华：仅写“担保”、未约定方式，按一般保证处理（《民法典》第686条）；未约定保证期间，为主债务到期后六个月（第692条）。第一笔2024-06-10到期，保证期间至2024-12-10，王芳此前未向其主张，保证责任很可能已消灭——不建议列为被告。\"}}]}}, {\"object\": \"block\", \"id\": \"e08e7f73-4603-46e0-82df-1e777eb4e8aa\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"配偶刘敏：借款用于炒股且刘敏明确不认，超出家庭日常生活需要，原则上不属夫妻共同债务（《民法典》第1064条）。除非能证明款项用于共同生活/共同经营，否则不建议列为共同被告。\"}}]}}, {\"object\": \"block\", \"id\": \"b0398e52-5da9-4c77-8546-b014c766b74b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉求筛选：精神损失费、误工损失在民间借贷纠纷中通常无法律依据，建议剔除；可主张本金、受保护利息及诉讼费用。最终诉求金额需王芳确认。\"}}]}}, {\"object\": \"block\", \"id\": \"b5dbd87b-6fe3-4444-82d7-57c2e7acfe75\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉讼费：财产案件按标的额分段累计，原告先行预交、败诉方最终负担。以本金56万元估算受理费约9,400元（利息计入后略增）。\"}}]}}, {\"object\": \"block\", \"id\": \"c4ecee2a-e867-4c01-8e53-151cbefdf174\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_1\", \"heading_1\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"七、主要风险\"}}]}}, {\"object\": \"block\", \"id\": \"7b4b0e40-0865-446c-8891-e9287c843b12\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"第二笔20万元现金交付举证薄弱：仅有借条，无取现/转账/收条，存在交付事实不被认定的败诉风险（杭州法院立案须知⑤；浙高法民间借贷指引）。\"}}]}}, {\"object\": \"block\", \"id\": \"8751e076-864b-4a8d-8ba9-9379266908fd\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"陈强急售宁波房产：若不及时保全，判决后可能无财产可供执行。保全需提供担保，且申请错误可能承担赔偿责任，须王芳决定。\"}}]}}, {\"object\": \"block\", \"id\": \"2765dfb4-03c3-4b78-88f8-c3d23833fa17\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"月息2%超出司法保护上限，利息不能按约定全额主张。\"}}]}}, {\"object\": \"block\", \"id\": \"3343b196-b077-4884-83ca-8594cb8c270a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_ed