structuredContent:
{
  "result": "{\"article_id\": \"art_cpl_103\", \"statute_id\": \"stat_cpl\", \"statute_name\": \"中华人民共和国民事诉讼法\", \"article_no\": \"第一百零三条\", \"heading\": \"诉讼财产保全\", \"text\": \"人民法院对于可能因当事人一方的行为或者其他原因，使判决难以执行或者造成当事人其他损害的案件，根据对方当事人的申请，可以裁定对其财产进行保全；人民法院采取保全措施，可以责令申请人提供担保，申请人不提供担保的，裁定驳回申请。\"}"
}

structuredContent:
{
  "result": "{\"article_id\": \"art_cpl_164\", \"statute_id\": \"stat_cpl\", \"statute_name\": \"中华人民共和国民事诉讼法\", \"article_no\": \"第一百六十四条\", \"heading\": \"上诉期间\", \"text\": \"当事人不服地方人民法院第一审判决的，有权在判决书送达之日起十五日内向上一级人民法院提起上诉。不服第一审裁定的，上诉期间为十日。\"}"
}

