  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"deeec620-6ee3-4997-8130-2d8fb32a2518\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"2026-05-28 法院缴费公告\"}}]}}, {\"object\": \"block\", \"id\": \"3984d71d-89e3-4080-8191-0dee6378efad\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"受理费：按诉请金额分段累计，原告立案时预交，审结后由败诉方负担。本案按76.94万估算约¥11,494。\"}}]}}, {\"object\": \"block\", \"id\": \"30d29712-38a4-44ae-86c2-dec5fd6c296c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"保全申请费：另按保全财产数额交纳（《诉讼费用交纳办法》第14条）：不超过1,000元每件30元；1千至10万部分1%；超过10万部分0.5%；最高不超过5,000元。保全56万约¥3,320，保全76.94万约¥4,367。\"}}]}}, {\"object\": \"block\", \"id\": \"e0e7351e-412a-4821-8321-c8c5100c09dc\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"保全还需提供担保（保险保函/现金/房产）；保险保函费用一般另计，通常为保全金额的一定比例，需向保险公司询价。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
