  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"b91830ca-4791-4673-8a48-2656cfaf2f8e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_1\", \"heading_1\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"十六、财产保全与防止转移财产（2026-05-28）\"}}]}}, {\"object\": \"block\", \"id\": \"e4b815a1-e26f-4d3d-8725-812f9021836b\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"🚨\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"房子被卖掉、过户给第三人，判决后可能无财产可执行。保全要尽早，但是否申请、保全多少、用什么担保，必须王芳决定。\"}}]}}, {\"object\": \"block\", \"id\": \"20c40c22-64e6-4a3a-8fa7-4fff88b2023d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"一、影响\"}}]}}, {\"object\": \"block\", \"id\": \"40a97a27-66fc-4045-8040-7c32ef660e97\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"若陈强把房子按市场价卖给不知情的第三人并过户，原则上不能再追房子，只能追房款；房款若被转走，执行难度大增。\"}}]}}, {\"object\": \"block\", \"id\": \"e351ed67-9f07-4d95-8d28-3cec097f1e5f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"若是明显低于市场价卖给亲友，可能构成《民法典》第538、539条的债权人撤销情形，但这是事后救济，举证难、周期长。\"}}]}}, {\"object\": \"block\", \"id\": \"ecc7bd8b-1664-4520-83f7-ccf83ff9edca\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"二、两条保全路径\"}}]}}, {\"object\": \"block\", \"id\": \"8fa78715-2409-4957-82b1-b1386b156b76\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉前财产保全：起诉前申请，适用于“情况紧急、不立即保全将难以执行”。需提供担保；法院采取措施后30日内必须起诉，否则解除保全（《民事诉讼法》第104条）。适合房子马上要过户的情形。\"}}]}}, {\"object\": \"block\", \"id\": \"79fa5090-9c3d-4bed-8b73-46a058c15263\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"诉中财产保全：与起诉同时或立案后申请（《民事诉讼法》第103条）。程序上更顺，但如果房子已经在谈过户，可能慢一步。\"}}]}}, {\"object\": \"block\", \"id\": \"18e7e51c-c241-493e-8f7e-3b2ffca4036f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"本案建议：让律师评估“诉前”还是“诉中”。如果挂牌只是试探、还没买家，诉中保全可与立案同步；如果已有带看/签约迹象，优先诉前。\"}}]}}, {\"object\": \"block\", \"id\": \"b7046dcc-e0f8-48a0-8c89-5615cfae39fd\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"三、保全对象与成本\"}}]}}, {\"object\": \"block\", \"id\": \"a9eeab3c-179d-44f6-88bd-66ad5e95aebd\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"对象：宁波海曙房产（查封）；如知道账户，也可申请冻结银行账户、微信/支付宝。\"}}]}}, {\"object\": \"block\", \"id\": \"86d6a9b6-b45f-44e9-8d30-8ae672074fbf\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"保全申请费：按保全金额算，保全56万约¥3,320，保全76.94万约¥4,373（最高5,000）。\"}}]}}, {\"object\": \"block\", \"id\": \"c5e21280-4720-4c7f-83e8-0fcfaacf0451\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"担保：保险保函、现金或房产；保险保函保费另计，需向保险公司询价（通常为保全金额的一定比例）。\"}}]}}, {\"object\": \"block\", \"id\": \"f59cf582-3ec2-4dc0-84e6-765c516ed969\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"风险：保全申请错误造成对方损失的，申请人要赔偿；不要超标的保全，第二笔20万若最终不被认定，保全金额过高会增加风险。\"}}]}}, {\"object\": \"block\", \"id\": \"ff73871c-bb76-459d-8d37-78e228a291b7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"四、现在就能做的证据固定\"}}]}}, {\"object\": \"block\", \"id\": \"f74bbab4-6855-4df9-833e-75f9b4746bbf\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"截图/录屏中介挂牌页：URL、挂牌时间、价格、面积、地址、中介电话；最好当天再录一次，显示时间。\"}}]}}, {\"object\": \"block\", \"id\": \"536288cd-d15a-4c26-8b87-754155c4c7f1\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"保存与中介/赵姐的聊天记录，能证明“急售、低于市场价”。\"}}]}}, {\"object\": \"block\", \"id\": \"a831df4c-d799-4074-82e5-0aae70ec5ff4\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"查房产登记信息（如能通过律师调查令/不动产登记查询），确认产权人、证号、有无抵押。\"}}]}}, {\"object\": \"block\", \"id\": \"3768d278-cf83-4946-89e6-31ba702b55e4\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"不要在公开渠道曝光陈强身份证号、住址等隐私；证据只交法院。\"}}]}}, {\"object\": \"block\", \"id\": \"493f6788-25cb-429c-88fa-5057fec18f0f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、需要王芳决定\"}}]}}, {\"object\": \"block\", \"id\": \"2d93b8bc-fa41-4228-8c80-cf0c95f04ae8\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"是否申请保全；诉前还是诉中；保全金额按56万还是76.94万；用保险保函还是现金/房产担保。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
