  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"14a26cf7-7fb8-4a64-8307-d2668884eeec\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_1\", \"heading_1\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"十七、管辖权异议应对（2026-05-30）\"}}]}}, {\"object\": \"block\", \"id\": \"d708db0d-1984-4f08-8f8a-6a4bc32bacae\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"🧭\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"初步判断：陈强提管辖异议，大概率不成立。西湖区法院有管辖权，建议坚持在西湖区审理；但最终是否坚持、是否上诉，由王芳决定。\"}}]}}, {\"object\": \"block\", \"id\": \"30193604-be7d-459e-832c-cc6cdb1f1ae1\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"一、法律依据\"}}]}}, {\"object\": \"block\", \"id\": \"591c5ca1-36c3-4696-83af-074ac71ca921\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《民事诉讼法》第24条：合同纠纷由被告住所地或者合同履行地人民法院管辖。\"}}]}}, {\"object\": \"block\", \"id\": \"05b09d0c-48dc-4a13-8fad-6fbb59efe616\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《民间借贷司法解释》第2条：出借人主张返还借款的，接收货币一方为出借人，出借人住所地为合同履行地。\"}}]}}, {\"object\": \"block\", \"id\": \"3ce4b8d4-ce1d-43bf-8177-800b566f4d18\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《民事诉讼法》第127条：管辖异议应在提交答辩状期间提出，法院审查后裁定驳回或移送。\"}}]}}, {\"object\": \"block\", \"id\": \"730b97ee-17f1-4267-88cc-dbcdd2712a45\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"《民事诉讼法》第164条：不服一审裁定的，上诉期为10日。\"}}]}}, {\"object\": \"block\", \"id\": \"ea1c9c8a-e6d0-4bd9-8e4e-02abea82571e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"类案：case_009（2025）浙0106民初09015号，西湖区法院已驳回同类型“应由被告住所地管辖”的异议。\"}}]}}, {\"object\": \"block\", \"id\": \"a1a0bec5-5ccf-4448-897e-4ed30a475f68\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"二、答辩要点（可直接改成答辩状）\"}}]}}, {\"object\": \"block\", \"id\": \"8267fd9c-3f83-4fe4-824f-4a50d6b4b585\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"本案争议标的是给付货币（返还借款），接收货币一方是出借人王芳，王芳住所地在杭州市西湖区，故西湖区是合同履行地。\"}}]}}, {\"object\": \"block\", \"id\": \"8ab0d976-4433-4a5f-86ab-3aae497bb57d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"依《民事诉讼法》第24条，被告住所地或合同履行地法院都有管辖权，原告有权选择向合同履行地法院起诉。\"}}]}}, {\"object\": \"block\", \"id\": \"46eaab82-1fa8-424b-8d4b-1fa580ceff79\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"借条未约定管辖法院，也未约定履行地，不排除法定管辖；陈强住所在宁波，不影响西湖区法院行使管辖权。\"}}]}}, {\"object\": \"block\", \"id\": \"5c4c253b-5285-46b9-8dd9-ad3d300bcdae\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"陈强若主张“只能由被告住所地管辖”，与司法解释第2条相悖；其可选择宁波起诉，不等于王芳不能选杭州。\"}}]}}, {\"object\": \"block\", \"id\": \"1d15a65d-97bc-479b-8f2a-6b842f37dbad\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"请求法院驳回管辖权异议，继续审理本案。\"}}]}}, {\"object\": \"block\", \"id\": \"77449812-ff36-4abd-8fdf-2c4d4866d682\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"三、三个回应方案（供王芳选）\"}}]}}, {\"object\": \"block\", \"id\": \"9acbedf1-d24c-4d52-840d-60729a64b5eb\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"方案A（建议）：坚持西湖区管辖。提交管辖异议答辩状+借条+转账回单+原告住所证明+case_009。优点：符合法律和判例，主场作战；缺点：可能拖1-3个月。\"}}]}}, {\"object\": \"block\", \"id\": \"a20f56b0-8d40-4ba8-8382-8becc3c8d7f7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"方案B：不争，同意移送宁波海曙。优点：快点进入实体审理；缺点：要去宁波应诉，成本高，且不利于保全和执行衔接。\"}}]}}, {\"object\": \"block\", \"id\": \"0e2d6f60-8d85-4c69-88dc-33a1c4f2415a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"方案C：先看陈强的具体异议理由再定。如果他只是泛泛说“应由被告住所地管辖”，按方案A；如果他拿出西湖区无管辖权的特殊证据，再评估。\"}}]}}, {\"object\": \"block\", \"id\": \"fa325c63-9eca-454f-85f6-3f76c11d6e52\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"四、需要王芳确认\"}}]}}, {\"object\": \"block\", \"id\": \"10420245-9c6c-4c95-848f-0e1af53bc7bb\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"是否坚持在西湖区法院审理（我建议坚持）。\"}}]}}, {\"object\": \"block\", \"id\": \"df686651-8566-45a7-8bb7-022355ced858\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"是否已收到法院转来的异议书副本/通知？请把原文或照片给我，看陈强的具体理由和法院给的答辩期限。\"}}]}}, {\"object\": \"block\", \"id\": \"0d554f56-08d9-4d1d-811e-c03621c55e26\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"能否提供西湖区居住证明：身份证、户口簿、房产证/租赁合同、社区证明，任选其二。\"}}]}}, {\"object\": \"block\", \"id\": \"0cc6b07c-9621-4e50-80d1-3485e861fc0d\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"是否已委托周敏律师？如已委托，由她提交答辩状；如未委托，我可以先出草稿，你签字提交。\"}}]}}, {\"object\": \"block\", \"id\": \"30dd5146-e18f-436a-8368-67d57f66195c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"如果法院裁定移送宁波，是否在10日内上诉？这个决定要等裁定出来再定。\"}}]}}, {\"object\": \"block\", \"id\": \"853e9b5c-0c07-4c24-8622-8e3672ada298\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"五、要准备的材料\"}}]}}, {\"object\": \"block\", \"id\": \"5921d171-eb90-415e-85dc-5662681b9737\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"管辖权异议答辩状（按法院通知期限提交）。\"}}]}}, {\"object\": \"block\", \"id\": \"cebcd373-02fc-486b-8d34-4f2a4ac4abc6\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"原告身份证、户口簿/居住证明（证明住所地在西湖区）。\"}}]}}, {\"object\": \"block\", \"id\": \"b85ba910-8a5e-43b4-8947-557c8eaf2cf5\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"借条、36万转账回单（证明借贷关系及履行）。\"}}]}}, {\"object\": \"block\", \"id\": \"c2f7c0ef-18f6-4d9c-8d96-e29bfb95f1a5\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"case_009判决书/类案检索报告。\"}}]}}, {\"object\": \"block\", \"id\": \"53b6d97a-3099-4fc4-8b80-777db1409a4a\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"陈强异议书副本及送达材料（收到后核对）。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
