\": \"block\", \"id\": \"1fc1cbaf-0207-46ea-82a2-19ea7a868b22\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6d9969b2-016d-4360-823a-960c9f15cfa5\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"如果没有新证据，只是觉得判得不公→ 上诉大概率维持原判，建议接受判决、尽快执行。\"}}]}}, {\"object\": \"block\", \"id\": \"0255984d-585d-468c-8434-4c837120052f\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6d9969b2-016d-4360-823a-960c9f15cfa5\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"如果陈强上诉→ 你作为被上诉人应诉；你自己想争第二笔的话，仍要在7/1前提交自己的上诉状，不要等他。\"}}]}}, {\"object\": \"block\", \"id\": \"fe686ba3-c1fe-4369-8820-a6f266be49c7\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6d9969b2-016d-4360-823a-960c9f15cfa5\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"见好就收的底线\"}}]}}, {\"object\": \"block\", \"id\": \"cbb67d37-95c1-4ce4-8067-66dc7daaf670\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6d9969b2-016d-4360-823a-960c9f15cfa5\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"不接受低于判决金额的调解；要谈也先算清278万？”不对，是27.6万。应以判决49.87万为底线，再谈第二笔。\"}}]}}, {\"object\": \"block\", \"id\": \"8484c24a-4ad9-45b4-800b-a37e3bbea535\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"6d9969b2-016d-4360-823a-960c9f15cfa5\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"如果陈强愿意一次性支付接近判决金额，可考虑和解；具体方案必须王芳确认。\"}}]}}], \"has_more\": false, \"next_cursor\": null, \"type\": \"block\", \"block\": {}}"
}

