  "result": "{\"object\": \"list\", \"results\": [{\"object\": \"block\", \"id\": \"9bef446b-01b2-47fd-85eb-6ee25f6b9d7e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_1\", \"heading_1\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"二十八、陈强上诉（2026-06-18）\"}}]}}, {\"object\": \"block\", \"id\": \"179097be-54a7-4e79-8c***\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"callout\", \"callout\": {\"icon\": {\"type\": \"emoji\", \"emoji\": \"🔔\"}, \"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"陈强不服一审判决，已向杭州市中级人民法院上诉，中院已受理。一审判决尚未生效，案件进入二审；王芳是被上诉人。\"}}]}}, {\"object\": \"block\", \"id\": \"d615c94e-0f23-4d15-8623-d619a9f34136\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"一、最关键的期限\"}}]}}, {\"object\": \"block\", \"id\": \"dd9f15e3-56c3-4a38-8e63-135df0101ff2\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"陈强上诉不影响王芳自己的上诉权：王芳要争第二笔20万，仍须在2026-07-01前提交自己的上诉状，并按上诉金额预交上诉费（约5,440元）。\"}}]}}, {\"object\": \"block\", \"id\": \"e8cbc800-42ac-4485-8662-02943bdaf00c\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"不提交自己的上诉状：二审只审陈强的上诉请求，第二笔20万的驳回部分将确定，王芳只能防守，不能要求二审加判。\"}}]}}, {\"object\": \"block\", \"id\": \"b99aeb0b-13cd-4d96-8324-b0ade5dad466\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"bulleted_list_item\", \"bulleted_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"答辩期限：收到上诉状副本后按法院通知的举证期限提交答辩与证据；通常为收到副本后15日内，具体以通知为准。\"}}]}}, {\"object\": \"block\", \"id\": \"794c422e-ed5f-46cf-87ae-b490f0e1dd82\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"二、马上要做\"}}]}}, {\"object\": \"block\", \"id\": \"d6836569-46a8-4b70-8b11-de6f667813fc\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"拿到陈强的上诉状副本：看他到底上诉什么——是不认36万本金、还是争利息、时效、还款，决定答辩重点。\"}}]}}, {\"object\": \"block\", \"id\": \"fab31653-db1e-453c-8d04-cbdbc93cb153\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"决定是否“跟上诉”：如果王芳要争第二笔20万，7/1前必须自己交上诉状；不交就放弃。\"}}]}}, {\"object\": \"block\", \"id\": \"24c5ba85-3e38-48ff-8990-5889821e7f1e\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"准备二审答辩状：一审认定事实清楚、适用法律正确，请求驳回上诉、维持原判。\"}}]}}, {\"object\": \"block\", \"id\": \"836d37a6-23fe-44a5-8dc3-d359a8b43c17\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"numbered_list_item\", \"numbered_list_item\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"证据：一审已提交的证据继续有效；如有新证据（取现记录/微信承认20万），在二审举证期限内提交。\"}}]}}, {\"object\": \"block\", \"id\": \"18b48eff-1e27-42ff-8026-66da87c14f16\", \"parent\": {\"type\": \"page_id\", \"page_id\": \"00f08177-9b83-4543-8a42-6470b5435b77\"}, \"created_time\": \"2026-01-01T00:00:00.000Z\", \"last_edited_time\": \"2026-01-01T00:00:00.000Z\", \"has_children\": false, \"archived\": false, \"in_trash\": false, \"type\": \"heading_2\", \"heading_2\": {\"rich_text\": [{\"type\": \"text\", \"text\": {\"content\": \"三、二审答辩要点（